codeExamples.code:
-- Session A
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 1; -- not yet committed

-- Session B (running concurrently)
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
BEGIN;
SELECT balance FROM accounts WHERE id = 1; -- DIRTY READ: sees the -100 change
COMMIT;

-- Session A decides to abort
ROLLBACK; -- the -100 never actually happened

-- Session A
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
BEGIN;
SELECT balance FROM accounts WHERE id = 1;  -- returns 100 (snapshot taken)

-- Session B commits a change concurrently
BEGIN;
UPDATE accounts SET balance = 150 WHERE id = 1;
COMMIT;

-- Session A re-reads
SELECT balance FROM accounts WHERE id = 1;  -- still returns 100, NOT 150
COMMIT;
